const assets={"cover_rId3": {"name": "csp-cover-image2.png", "data": ""}, "cover_rId4": {"name": "csp-cover-image3.jpeg", "data": ""}, "cover_rId5": {"name": "csp-cover-image4.png", "data": ""}};
export async function applyQuarterlyCover(bytes:Blob|ArrayBuffer|Uint8Array|string,year:number,quarter:number){
 const zip=await JSZip.loadAsync(bytes instanceof Blob?await bytes.arrayBuffer():bytes);
 const period='Mouvements '+['de janvier à mars','d’avril à juin','de juillet à septembre','d’octobre à décembre'][quarter-1]+' '+year;
 zip.file('ppt/slides/slide1.xml',coverXml.replace('__CSP_PERIOD__',period));
 const path='ppt/slides/_rels/slide1.xml.rels';
 const rels=await zip.file(path)!.async('string');
 let additions='';
 for(const [id,asset] of Object.entries(assets)){
  zip.file('ppt/media/'+asset.name,asset.data,{base64:true});
  additions+='<Relationship Id="'+id+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/'+asset.name+'"/>';
 }
 zip.file(path,rels.replace('</Relationships>',additions+'</Relationships>'));
 // The original ULM logo is JPEG. Register the extension even when the generated
 // report happens to contain only PNG images.
 const typesPath='[Content_Types].xml';
 let types=await zip.file(typesPath)!.async('string');
 if(!types.includes('Extension="jpeg"'))types=types.replace('</Types>','<Default Extension="jpeg" ContentType="image/jpeg"/></Types>');
 zip.file(typesPath,types);
 return zip.generateAsync({type:'uint8array',compression:'DEFLATE'});
}
